// Checkout conversion module to track paid events
const fs = require('fs');
const path = require('path');

const REVENUE_LOG = '/var/log/revenue_events.log';

function logPaidEvent(amount, currency, userId) {
  const event = {
    type: 'paid',
    amount,
    currency: currency || 'USD',
    userId: userId || 'anonymous',
    timestamp: new Date().toISOString()
  };
  fs.appendFileSync(REVENUE_LOG, JSON.stringify(event) + '\n');
  return event;
}

function getPaidEventCount() {
  try {
    if (!fs.existsSync(REVENUE_LOG)) return 0;
    const data = fs.readFileSync(REVENUE_LOG, 'utf8');
    const lines = data.trim().split('\n').filter(l => l);
    return lines.length;
  } catch (e) {
    return 0;
  }
}

module.exports = { logPaidEvent, getPaidEventCount };
